import heapq

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    if (
        not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] == '.')
        or not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] == '.')
    ):
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    INF = float('inf')
    dist = [[INF] * cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0
    heap = [(0, start[0], start[1])]
    parent = {}

    while heap:
        d, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            break
        if d > dist[r][c]:
            continue
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                new_dist = d + 1
                if new_dist < dist[nr][nc]:
                    dist[nr][nc] = new_dist
                    parent[(nr, nc)] = (r, c)
                    heapq.heappush(heap, (new_dist, nr, nc))

    if goal not in parent:
        return []

    path = []
    curr = goal
    while curr != start:
        path.append(curr)
        curr = parent[curr]
    path.append(start)
    path.reverse()
    return path

