import random

def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal is out of bounds or is a wall
    if (0 <= start[0] < rows and 0 <= start[1] < cols and 0 <= goal[0] < rows and 0 <= goal[1] < cols):
        if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
            return []
    else:
        return []

    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    frontier = []
    seen = set()
    parent = {}

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    heapq.heappush(frontier, (random.random(), start[0], start[1]))
    seen.add(start)

    while frontier:
        _, r, c = heapq.heappop(frontier)
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if (nr, nc) == goal:
                parent[(nr, nc)] = (r, c)
                return reconstruct_path(start, (nr, nc), parent)
            if is_valid(nr, nc) and (nr, nc) not in seen:
                seen.add((nr, nc))
                parent[(nr, nc)] = (r, c)
                heapq.heappush(frontier, (random.random(), nr, nc))

    return []

def reconstruct_path(start, goal, parent):
    path = [goal]
    current = goal
    while current != start:
        current = parent[current]
        path.append(current)
    return path[::-1]

